package com.afterglow.player;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import java.util.*;import org.json.*;
public class LibraryChecks extends Instrumentation {
 String phase="start";interface Condition{boolean ok();}void await(Condition c,int seconds)throws Exception{for(int i=0;i<seconds*20;i++){if(c.ok())return;Thread.sleep(50);}throw new AssertionError("Timed out: "+phase);}void check(boolean ok,String name){if(!ok)throw new AssertionError(name);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{MainActivity a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(()->a.service!=null,10);PlaybackService p=a.service;
 runOnMainSync(()->{p.pause(true);p.releasePlayer();p.queue.clear();p.upcoming.clear();p.backlog.clear();p.collections.playlists.clear();p.repeat=p.repeatAll=false;p.index=0;for(int i=0;i<14;i++)p.queue.add(new Track("Track "+(char)('N'-i),"Artist "+i,"demo","local"));p.favorite(p.queue.get(2));check(p.collections.create("My mix"),"Create playlist");check(!p.collections.create(" my MIX "),"Duplicate name rejected");p.collections.add("My mix",p.queue.get(2));p.collections.add("My mix",p.queue.get(0));p.collections.add("My mix",p.queue.get(2));check(p.collections.members("My mix",p.queue).size()==2,"Duplicate membership skipped");p.save();LibraryCollections loaded=new LibraryCollections();loaded.load(p.prefs.getString("playlists","[]"));check(loaded.members("My mix",p.queue).get(0)==p.queue.get(2),"Playlist reload");a.library.favorites=true;check(a.library.indices().equals(Arrays.asList(2)),"Favourite filter");a.library.favorites=false;a.prefs.edit().putInt("librarySort",1).apply();check(a.library.indices().get(0)==13,"Title sorting");a.prefs.edit().putInt("librarySort",4).putLong("shuffleSeed",42).apply();List<Integer> mixed=a.library.indices();check(mixed.equals(a.library.indices()),"Stable shuffled view");check(new HashSet<>(mixed).size()==14,"Shuffle preserves every song");a.library.playlist="My mix";check(a.library.visible().size()==2,"Playlist view");a.library.playlist=null;a.prefs.edit().putInt("librarySort",0).apply();p.playSequence(new ArrayList<>(p.queue),false);});await(()->p.playing()&&p.nextPrepared,12);check(p.upcoming.size()==10&&p.backlog.size()==3,"Bounded download window for large playlist");
 Track saved=Track.from(p.queue.get(2).json());check(saved.favorite&&saved.id.equals(p.queue.get(2).id),"Favourite and ID persist");String stable=saved.id;saved.uri="changedvideo";check(saved.id.equals(stable),"Resolution preserves ID");
 phase="fade";runOnMainSync(()->p.seek(p.duration()-3500));await(()->p.fadeOut!=null,8);check(!p.nextPlayer.isPlaying(),"Next player remains stopped during fade");check(!p.crossfading&&p.fadeIn==null,"No crossfade");long deadline=SystemClock.elapsedRealtime()+8000;while(p.index==0){check(SystemClock.elapsedRealtime()<deadline,"Fade handoff deadline");check(p.nextPlayer==null||!p.nextPlayer.isPlaying(),"No overlapping audio");Thread.sleep(25);}await(()->p.index==1&&p.playing(),5);check(p.upcoming.size()==10&&p.backlog.size()==2,"Playlist window replenishes");
 phase="repeat all";runOnMainSync(()->{p.playSequence(Arrays.asList(p.queue.get(0),p.queue.get(1),p.queue.get(2)),false);p.repeat=false;p.repeatAll=true;p.save();});await(()->p.playing()&&p.index==0,10);for(int expected:new int[]{1,2,0}){runOnMainSync(()->p.seek(p.duration()-600));final int target=expected;await(()->p.index==target&&p.playing(),8);check(p.upcoming.size()<=10,"Repeat queue cap");}check(p.prefs.getBoolean("repeatAll",false),"Repeat-all persisted");
 phase="repeat one";runOnMainSync(()->{p.cycleRepeat();check(p.repeat&&!p.repeatAll,"Cycle to repeat one");p.seek(p.duration()-600);});Thread.sleep(1500);check(p.index==0&&p.playing()&&p.position()<4000,"Repeat-one restarts same song");runOnMainSync(()->{p.cycleRepeat();check(!p.repeat&&!p.repeatAll,"Cycle to off");p.upcoming.clear();p.backlog.clear();p.seek(p.duration()-500);});await(()->p.ended,6);runOnMainSync(()->p.seek(500));await(()->p.playing()&&p.position()<4000,6);
 runOnMainSync(()->{p.pause(true);p.releasePlayer();Track removed=p.queue.get(2);p.removeTrack(removed);check(!p.collections.playlists.get("My mix").contains(removed.id),"Deletion cleans playlist membership");a.page=0;a.render();});waitForIdleSync();android.graphics.Bitmap shot=getUiAutomation().takeScreenshot();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),"library-update.png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}result.putString("result","PASS: favourites, stable IDs, playlists and reload, sorting/shuffle, bounded playlist queue, fade-out without overlap, repeat all/one/off and seek restart");
 }catch(Throwable e){result.putString("failure",phase+": "+e.toString());}finish(result.containsKey("failure")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
}

